def split_for(index: int) -> str:
    if index and index % 23 == 0: return "cross_domain_holdout"
    if index and index % 17 == 0: return "sealed_test"
    if index and index % 13 == 0: return "validation"
    return "train"


def base(identifier: str, domain: str, subject: str, sources: list[str], split: str, kind: str, epistemic: str = "interpretive") -> dict[str, Any]:
    return {"schema_version":1,"record_id":identifier,"world_id":WORLD,"domain_id":domain,"subject_id":subject,"lanes":LANES,"record_kind":kind,"epistemic_class":epistemic,"coverage_axes":["definitions_scope","primitives_invariants","mechanisms_causal_laws"],"source_ids":sorted(set(sources)),"scope":"arts, society, economics, law, history, geography, and culture foundation tranche","limitations":["Interpretations retain source, audience, culture, time, power, method, and counterreading boundaries.","Legal claims require live primary-source verification in the applicable jurisdiction and are not individualized legal advice.","Economic and social models retain measurement, institution, distribution, identification, and value assumptions."],"as_of":"2026-09-03","version_boundary":"society-culture-arts-v0","split_group":identifier,"split":split,"tags":["foundation",domain]}


def context(prefix: str) -> tuple[str,list[str],str]:
    for p,domain,profiles,sources,_label,_statement in GROUPS:
        if p==prefix:return domain,sources,profiles[0][0]
    raise ValueError(prefix)


def build()->list[dict[str,Any]]:
    records=[];index=0
    for prefix,domain,profiles,sources,domain_label,domain_statement in GROUPS:
        records.append({**base(f"{prefix}.root",domain,profiles[0][0],sources,"train","concept"),"label":domain_label,"statement":domain_statement,"aliases":[domain_label.lower()]})
        for subject,slug,label,definition,primitive_label,primitive_statement,mechanism_label,mechanism_statement,control_label,control_statement in profiles:
            for offset,(suffix,node_label,statement) in enumerate([("root",label,definition),("primitive",primitive_label,primitive_statement),("mechanism",mechanism_label,mechanism_statement)]):
                nid=f"{prefix}.{slug}.{suffix}";records.append({**base(nid,domain,subject,sources,"train" if suffix=="root" else split_for(index+offset),"concept"),"label":node_label,"statement":statement,"aliases":[node_label.lower()]})
                target=f"{prefix}.root" if suffix=="root" else f"{prefix}.{slug}.root";rid=f"sca.membership.{prefix}.{slug}.{suffix}"
                records.append({**base(rid,domain,subject,sources,split_for(index+offset+4),"relation"),"label":f"{node_label} world membership","statement":f"{node_label} is a distinct component of {label} with explicit source, context, model, and interpretation boundaries.","aliases":[],"relation":{"source_node":nid,"target_node":target,"kind":"part_of","polarity":1,"direction":"forward","conditions":["the declared culture, institution, time, population, and source context apply"],"exceptions":[]},"coverage_axes":["primitives_invariants","within_domain_composition"]})
            cid=f"sca.control.{prefix}.{slug}";records.append({**base(cid,domain,subject,[],["train","validation","sealed_test","cross_domain_holdout"][index%4],"synthetic_control","synthetic_control"),"label":control_label,"statement":control_statement,"aliases":[control_label.lower()],"synthetic":True,"coverage_axes":["exceptions_boundaries","errors_adversarial_misuse","unknown_abstention"],"tags":["negative-control",domain]});index+=1
    all_sources=sorted({s for _p,_d,_profiles,sources,_l,_st in GROUPS for s in sources});splitter=RelationSplitter([kind for _id,_s,_t,kind,_st in CROSS_RELATIONS])
    for identifier,source,target,kind,statement in CROSS_RELATIONS:
        prefix=source.split(".",1)[0];domain,sources,subject=context(prefix);cross=prefix!=target.split(".",1)[0] or identifier.startswith("bridge-")
        records.append({**base(f"sca.relation.{identifier}",domain,subject,all_sources if cross else sources,splitter.split(kind,cross_requested=cross),"relation"),"label":identifier.replace("-"," "),"statement":statement,"aliases":[],"relation":{"source_node":source,"target_node":target,"kind":kind,"polarity":-1 if kind in {"inhibits","prevents","contradicts","undercuts"} else 1,"direction":"forward","conditions":["source, culture, institution, jurisdiction, population, model, and time assumptions hold"],"exceptions":[]},"coverage_axes":["mechanisms_causal_laws","within_domain_composition","cross_domain_composition"]})
    for ei,(prefix,identifier,label,statement,subject) in enumerate(WORKED_EXAMPLES):
        domain,sources,_=context(prefix);split=["train","validation","sealed_test","cross_domain_holdout"][ei%4];nid=f"sca.example.{prefix}.{identifier}"
        records.append({**base(nid,domain,subject,sources,split,"worked_example"),"label":label,"statement":statement,"aliases":[],"coverage_axes":["applications_toolchains","deductions_predictions_execution","uncertainty_competing_hypotheses"],"tags":["worked-example",domain]})
        records.append({**base(f"sca.example-membership.{prefix}.{identifier}",domain,subject,sources,split,"relation"),"label":f"{label} membership","statement":f"The {label.lower()} operationalizes one bounded interpretive, social, legal, historical, artistic, or economic evidence chain.","aliases":[],"relation":{"source_node":nid,"target_node":f"{prefix}.root","kind":"part_of","polarity":1,"direction":"forward","conditions":["the example remains bounded and non-authoritative"],"exceptions":[]},"coverage_axes":["applications_toolchains","within_domain_composition"]})
    return sorted(records,key=lambda x:x["record_id"])


def main()->int:
    records=build();OUTPUT.parent.mkdir(parents=True,exist_ok=True);OUTPUT.write_text("".join(json.dumps(x,ensure_ascii=False,sort_keys=True)+"\n" for x in records),encoding="utf-8");counts={};kinds={}
    for x in records:counts[x["split"]]=counts.get(x["split"],0)+1;kinds[x["record_kind"]]=kinds.get(x["record_kind"],0)+1
    print(f"wrote {OUTPUT} with {len(records)} records: splits={dict(sorted(counts.items()))} kinds={dict(sorted(kinds.items()))}");return 0


if __name__=="__main__":raise SystemExit(main())
